def weapons(me, enemy, arena):
    w = me.weapons.get("front")
    if w is None or w.get("type") != "spinner":
        return None
    if not me.can_drive:
        return None

    maxr = w.get("max_rpm", 2500)
    temp = w.get("temperature", 25.0)
    target = maxr
    if temp > 150:
        target = 0
    elif temp > 135:
        target = maxr * 0.5
    if me.battery_wh < 50:
        target = 0

    return spin("front", int(target))

def drive(me, enemy, arena):
    # Simple proportional steering toward the opponent
    bearing = me.bearing_to(enemy.x, enemy.y)  # degrees, positive = left of heading
    if abs(bearing) < 5:
        # go straight forward
        return (1.0, 1.0)
    elif bearing > 0:
        # turn left (slow left wheel)
        return (0.4, 1.0)
    else:
        # turn right (slow right wheel)
        return (1.0, 0.4)

